// santiagodie.com: behaviour only. Every word on the page is already in the HTML
// generated by tools/build.py; this script never injects content.
// Handles: header state on scroll, mobile menu, language menu
// (menu button pattern) and the dismissible language suggestion.

(() => {
  "use strict";

  const header = document.querySelector("[data-header]");
  const toggle = document.querySelector("[data-menu-toggle]");
  const menu = document.querySelector("[data-menu]");
  const compact = window.matchMedia("(max-width: 63.99em)");
  const lang = document.documentElement.lang;
  const langSwitch = document.querySelector("[data-lang-switch]");
  const langButton = langSwitch.querySelector("button");
  const langItems = [...langSwitch.querySelectorAll("[role='menuitem']")];


  // Storage can throw (private mode, blocked cookies), so every access is guarded.
  const storage = {
    get(key) {
      try { return window.localStorage.getItem(key); } catch { return null; }
    },
    set(key, value) {
      try { window.localStorage.setItem(key, value); } catch { /* not persisted */ }
    },
  };

  // Header: transparent over the hero, navy once the page scrolls -------------

  const onScroll = () => header.toggleAttribute("data-scrolled", window.scrollY > 16);
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // Mobile menu ---------------------------------------------------------------

  const label = toggle.querySelector(".menu-toggle__label");

  function setMenu(open, { returnFocus = false } = {}) {
    toggle.setAttribute("aria-expanded", String(open));
    header.toggleAttribute("data-menu-open", open);
    menu.inert = compact.matches && !open;
    label.textContent = open ? label.dataset.labelClose : label.dataset.labelOpen;
    if (!open) closeLang();
    if (!open && returnFocus) toggle.focus();
  }

  toggle.addEventListener("click", () => setMenu(toggle.getAttribute("aria-expanded") !== "true"));
  menu.addEventListener("click", (event) => {
    if (compact.matches && event.target.closest("[data-nav-link]")) setMenu(false);
  });
  compact.addEventListener("change", () => setMenu(false));
  setMenu(false);

  // Language menu (WAI-ARIA menu button: arrows, Home/End, Enter, Escape) -------

  function openLang(focusIndex = 0) {
    langSwitch.setAttribute("data-open", "");
    langButton.setAttribute("aria-expanded", "true");
    langItems[Math.max(0, Math.min(focusIndex, langItems.length - 1))].focus({ preventScroll: true });
  }

  function closeLang({ returnFocus = false } = {}) {
    if (!langSwitch.hasAttribute("data-open")) return;
    langSwitch.removeAttribute("data-open");
    langButton.setAttribute("aria-expanded", "false");
    if (returnFocus) langButton.focus();
  }

  langButton.addEventListener("click", () => {
    if (langSwitch.hasAttribute("data-open")) closeLang();
    else openLang(Math.max(0, langItems.findIndex((item) => item.hasAttribute("aria-current"))));
  });

  langButton.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation(); // the menu's own handler would move focus a second time
      openLang(event.key === "ArrowDown" ? 0 : langItems.length - 1);
    }
  });

  langSwitch.addEventListener("keydown", (event) => {
    const index = langItems.indexOf(document.activeElement);
    if (index === -1) return;
    const moves = { ArrowDown: index + 1, ArrowUp: index - 1, Home: 0, End: langItems.length - 1 };
    if (event.key in moves) {
      event.preventDefault();
      langItems[(moves[event.key] + langItems.length) % langItems.length].focus({ preventScroll: true });
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeLang({ returnFocus: true });
    } else if (event.key === "Tab") {
      closeLang();
    }
  });

  // Keep the reader in the same section when switching language.
  langItems.forEach((item) => {
    item.addEventListener("click", () => {
      const section = currentSection();
      if (section && !item.hasAttribute("aria-current")) item.hash = section;
    });
  });

  document.addEventListener("click", (event) => {
    if (!langSwitch.contains(event.target)) closeLang();
    if (header.hasAttribute("data-menu-open") && !header.contains(event.target)) setMenu(false);
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (langSwitch.hasAttribute("data-open")) closeLang({ returnFocus: true });
    else if (header.hasAttribute("data-menu-open")) setMenu(false, { returnFocus: true });
  });

  // Current section: js/scroll.js marks it in the navigation, following the tip of
  // the progress line.

  function currentSection() {
    const link = document.querySelector("[data-nav-link][aria-current]");
    return link ? link.getAttribute("href").slice(1) : null;
  }

  // Language suggestion: a hint, never a redirect -------------------------------

  // The inline script in <head> already chose the language to suggest (if any)
  // before the first paint, so the bar never pushes the page down.
  const DISMISS_KEY = "lang-suggest-dismissed";
  const preferred = document.documentElement.dataset.suggest;
  const suggestion = preferred && document.querySelector(`.lang-suggest[data-suggest="${preferred}"]`);

  if (suggestion && preferred !== lang) {
    suggestion.hidden = false;
    suggestion.querySelector("[data-suggest-dismiss]").addEventListener("click", () => {
      suggestion.hidden = true;
      delete document.documentElement.dataset.suggest;
      storage.set(DISMISS_KEY, "1");
    });
  }
})();
